package vn.edu.toeic.dataset;
import com.google.gson.*;
import java.nio.file.*;
import org.jsoup.Jsoup;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import static vn.edu.toeic.dataset.Json.*;
class RecoveryTest {
 @TempDir Path temp;
 JsonObject recover(String body) {return new ExplanationRecovery().recover(Jsoup.parse("<article id='cau-101' data-question-number='101' data-part-name='Part 5'><div class='zen-history-sub-question'>101. Choose the original example.</div><div class='zen-history-answer-details'><p><strong>Đáp án đúng:</strong>B. Beta</p></div><div class='zen-history-explanation'>"+body+"</div></article>").selectFirst("article"),"MOCK.html","a".repeat(64));}
 String option(JsonObject r,String id) {return str(r.getAsJsonObject("originalEnglishOptions").getAsJsonObject(id),"value");}
 @Test void vietnameseAndUnaccentedTranslationNeverBecomeEnglish() {assertTrue(ExplanationRecovery.vietnamese("Giá cao"));assertTrue(ExplanationRecovery.vietnamese("day la dap an dung"));assertFalse(ExplanationRecovery.english("Người phụ nữ"));assertFalse(ExplanationRecovery.english("Trang 2"));assertFalse(ExplanationRecovery.english("Giao hoa"));assertNull(option(recover("<p>(A) Giá cao<br>(C) day la dap an dung</p>"),"A"));}
 @Test void labelsArePreservedDespiteOrder() {var r=recover("<ul><li>D. Delta</li><li>A. Alpha</li><li>C. Gamma</li><li>B. Beta</li></ul>");assertEquals("Alpha",option(r,"A"));assertEquals("Delta",option(r,"D"));}
 @Test void tableCellsHaveExplicitLabelEvidence() {var r=recover("<table><tr><td>C</td><td>Gamma</td><td>MOCK gloss</td></tr><tr><td>A</td><td>Alpha</td></tr></table>");assertEquals("Gamma",option(r,"C"));assertFalse(r.getAsJsonObject("originalEnglishOptions").getAsJsonObject("C").getAsJsonArray("provenance").isEmpty());}
 @Test void positionMarkersPreserveLabelsWithoutCallingThemEnglish() {var r=recover("<p>(D) [4]<br>(A) [1]<br>(C) [3]</p>");assertEquals("[1]",option(r,"A"));assertEquals("POSITION_MARKER",str(r.getAsJsonObject("originalEnglishOptions").getAsJsonObject("A"),"contentKind"));assertFalse(ExplanationRecovery.english("[1]"));}
 @Test void resumeLoanwordInEnglishQuestionIsNotVietnamese() {assertTrue(ExplanationRecovery.english("106. The hiring manager considered each applicant’s résumé and qualifications."));}
 @Test void unlabelledVocabularyNeverGetsGuessedLabels() {var r=recover("<p>– Alpha: từ thứ nhất<br>– Gamma: từ thứ ba<br>– Delta: từ thứ tư</p>");assertNull(option(r,"A"));assertEquals("Beta",option(r,"B"));}
 @Test void glossPrefixNeedsReviewAndMissingOptionsStayMissing() {var r=recover("<p>A. across: ngang qua</p>");assertEquals("across",option(r,"A"));assertEquals("EXTRACTED_NEEDS_REVIEW",str(r.getAsJsonObject("originalEnglishOptions").getAsJsonObject("A"),"status"));assertNull(option(r,"D"));}
 @Test void teacherSentenceIsNotRecoveredAsOriginalOption() {var r=recover("<p>A. The correct answer is Alpha because of grammar.</p>");assertNull(option(r,"A"));}
 @Test void conflictingOriginalTextsStayBlocked() {var r=recover("<p>A. Alpha<br>A. Different text</p>");assertNull(option(r,"A"));assertFalse(r.getAsJsonArray("conflicts").isEmpty());}
 JsonObject realRecovery(JsonObject d)throws Exception {var dom=Jsoup.parse(Files.readString(HtmlExamParserTest.ROOT.resolve("data/seedingTest/ets2026_test01.html")));var qs=new JsonArray();for(var a:dom.select("article[data-zen-history-answer]"))qs.add(new ExplanationRecovery().recover(a,"source.html",str(d.getAsJsonObject("source"),"sha256")));return obj("questions",qs);}
 JsonObject base()throws Exception{return new HtmlExamParser().parse(HtmlExamParserTest.ROOT,"data/seedingTest/ets2026_test01.html");}
 @Test void real200QuestionsKeepKeysAndNoListeningTranscript()throws Exception {var d=base();var r=realRecovery(d);var result=RecoverExam.reconstruct(d,r);assertEquals(200,num(result.getAsJsonObject("recovery-summary"),"recordedKeyLabelsCrossCheckedWithPreviousParser"));assertEquals(0,num(result.getAsJsonObject("recovery-summary"),"answerKeysIndependentlyVerified"));var draft=new V2Converter().draft(d);for(int n=0;n<31;n++){var q=draft.getAsJsonArray("questions").get(n).getAsJsonObject();for(var o:q.getAsJsonArray("options"))assertNull(str(o.getAsJsonObject(),"text"));for(var b:q.getAsJsonArray("blocks"))if("TEXT".equals(str(b.getAsJsonObject(),"type")))assertEquals((n+1)+".",str(b.getAsJsonObject(),"text"));}assertFalse(new DatasetValidator().validate(d).get("importable").getAsBoolean());}
 @Test void originalJsonJoinsByIdentityAndRejectsWrongKeyOrPart()throws Exception {var d=base();var r=realRecovery(d);Path file=temp.resolve("MOCK-original.json");var input=obj("examId","ets2026-test01","questions",arr(obj("questionNumber",101,"part",5,"correctOption","B","options",arr(obj("optionId","D","text","Delta"),obj("optionId","B","text","after"),obj("optionId","A","text","Alpha"),obj("optionId","C","text","Gamma")))));write(file,input);new OriginalContentJoin().apply(d,r,file);RecoverExam.reconstruct(d,r);assertEquals("Alpha",str(d.getAsJsonArray("questions").get(100).getAsJsonObject().getAsJsonArray("options").get(0).getAsJsonObject(),"text"));input.getAsJsonArray("questions").get(0).getAsJsonObject().addProperty("correctOption","A");write(file,input);assertThrows(IllegalArgumentException.class,()->new OriginalContentJoin().apply(d,r,file));}
 @Test void malformedDocumentMappingRejected()throws Exception {var d=base();var r=realRecovery(d);Path f=temp.resolve("MOCK-doc.json");write(f,obj("examId","ets2026-test01","questions",new JsonArray(),"groups",arr(obj("part",6,"questionNumbers",arr(131,133,134,135),"documents",arr(obj("documentId","doc","text","MOCK original document."))))));assertThrows(IllegalArgumentException.class,()->new OriginalContentJoin().apply(d,r,f));}
}
